// Stage 5 of the unified demo seed: enrollments (Task 6) — the front desk's
// membership-application queue.
//
// Exactly 10 pending + 45 confirmed. The pending count is the number the desk
// works from, so it is asserted exactly rather than generated by a probability
// roll. Resumable via data/enrollments.json.
//
// Usage:
//   node seed-enrollments.mjs              # full run
//   node seed-enrollments.mjs --dry-run    # generate + print, insert nothing
//
// Exit codes: 0 ok, 2 verification failed.
import { client, chunk, parseArgs, readManifest, writeManifest, localDate } from './lib/common.mjs'
import { buildEnrollments, PENDING_COUNT, CONFIRMED_COUNT, TOTAL } from './lib/enrollments.mjs'

const KEY = 'enrollments.json'
const args = parseArgs(process.argv.slice(2))
const dryRun = args['dry-run'] === true || args['dry-run'] === 'true'

async function adminId() {
  const { data, error } = await client.from('profiles').select('id').eq('role', 'admin').limit(1)
  if (error) throw new Error(`admin lookup: ${error.message}`)
  if (!data?.length) throw new Error('no admin profile found')
  return data[0].id
}

/** Ruling 3: Task 6's original "reassign and delete extra admin A002" is
 *  already satisfied — A002 does not exist. Assert the single admin instead. */
async function verifySingleAdmin() {
  const { data, error } = await client.from('profiles').select('id, code, email').eq('role', 'admin')
  if (error) throw new Error(`admin count: ${error.message}`)
  console.log(`admins: ${data.length} (${data.map((a) => `${a.code} ${a.email}`).join(', ')})`)
  return data.length === 1
}

async function main() {
  const started = Date.now()
  const admin = await adminId()

  let manifest = readManifest(KEY)
  if (!manifest?.rows?.length) {
    const built = buildEnrollments(admin)
    manifest = {
      generatedAt: new Date().toISOString(),
      asOf: built.asOf,
      total: built.rows.length,
      inserted: 0,
      rows: built.rows,
    }
    writeManifest(KEY, manifest)
    const pending = built.rows.filter((r) => r.status === 'pending').length
    console.log(
      `Generated ${built.rows.length} enrollment applications as of ${built.asOf}: ` +
      `${pending} pending / ${built.rows.length - pending} confirmed`,
    )
  } else {
    console.log(`Resuming: ${manifest.rows.length} rows, checkpoint ${manifest.inserted ?? 0}`)
  }

  const rows = manifest.rows
  if (dryRun) {
    console.log(`Dry run — ${rows.length - (manifest.inserted ?? 0)} rows would be written.`)
    return
  }

  const inserted = manifest.inserted ?? 0
  const pending = rows.slice(inserted)
  if (pending.length) {
    let done = inserted
    for (const c of chunk(pending, 400)) {
      const { error } = await client.from('enrollments').upsert(c, { onConflict: 'id', ignoreDuplicates: true })
      if (error) throw new Error(`enrollments upsert @${done}: ${error.message}`)
      done += c.length
      writeManifest(KEY, { ...readManifest(KEY), inserted: done })
    }
    console.log(`Upserted ${done - inserted} rows`)
  } else {
    console.log('Nothing pending — already complete')
  }

  await verify()
  console.log(`Total elapsed: ${((Date.now() - started) / 1000).toFixed(1)}s`)
}

async function verify() {
  const { data, error } = await client.from('enrollments').select('id, status, email, created_at, confirmed_at, confirmed_by')
  if (error) throw new Error(`verify: ${error.message}`)
  const pending = data.filter((r) => r.status === 'pending')
  const confirmed = data.filter((r) => r.status === 'confirmed')
  const badPending = pending.filter((r) => r.confirmed_at || r.confirmed_by).length
  const badConfirmed = confirmed.filter((r) => !r.confirmed_at || !r.confirmed_by).length
  const badOrder = confirmed.filter((r) => new Date(r.confirmed_at) < new Date(r.created_at)).length
  const emails = new Set(data.map((r) => r.email))
  const badEmail = [...emails].filter((e) => !e.endsWith('@demo.fit')).length
  const adminOk = await verifySingleAdmin()

  console.log('--- verification ---')
  console.log(`enrollments: ${data.length} (expected ${TOTAL})`)
  console.log(`status: ${pending.length} pending (expected ${PENDING_COUNT}) / ${confirmed.length} confirmed (expected ${CONFIRMED_COUNT})`)
  console.log(`unique emails: ${emails.size}/${data.length} · non-demo emails: ${badEmail}`)
  console.log(`pending with a decision: ${badPending} · confirmed without one: ${badConfirmed} · decided before requested: ${badOrder}`)

  const ok =
    data.length === TOTAL &&
    pending.length === PENDING_COUNT &&
    confirmed.length === CONFIRMED_COUNT &&
    emails.size === data.length &&
    badEmail === 0 && badPending === 0 && badConfirmed === 0 && badOrder === 0 &&
    adminOk
  if (!ok) {
    console.error('VERIFY FAILED')
    process.exit(2)
  }
  console.log('VERIFY PASSED')
}

main().catch((err) => {
  console.error('seed-enrollments FAILED:', err.message)
  process.exit(1)
})
